html:
{#- Tender BOQ (catalogue 2.6): the priced bill as the client sees it. Selling
    figures only: no cost rate, estimate, markup or margin ever appears here. -#}
{%- set ns = namespace(total=0) -%}
{%- set prelim = [] -%}
{%- set heads = {} -%}
{%- for row in doc.items if not row.is_contingency -%}
	{%- set key = row.cost_head or "" -%}
	{%- if key not in heads -%}{%- set _ = heads.update({key: []}) -%}{%- endif -%}
	{%- set _ = heads[key].append(row) -%}
{%- endfor -%}
{%- set prelim_heads = frappe.get_all("Cost Head", filters={"is_preliminaries": 1}, pluck="name") -%}
{%- set order = (heads.keys() | select("in", prelim_heads) | list) + (heads.keys() | reject("in", prelim_heads) | sort | list) -%}

<div class="tender-boq">
	<h2 style="margin-bottom: 4px;">{{ _("Bill of Quantities") }}</h2>
	<p style="margin: 0 0 12px; color: #555;">
		{%- if doc.opportunity %}{{ frappe.db.get_value("Opportunity", doc.opportunity, "title") or doc.opportunity }}<br>{% endif -%}
		{{ _("Client") }}: <b>{{ doc.client_name or doc.customer or "" }}</b>
		&nbsp;·&nbsp; {{ _("Date") }}: {{ frappe.utils.formatdate(doc.boq_date) }}
		{%- if doc.measurement_method %} &nbsp;·&nbsp; {{ _("Measured to") }} {{ doc.measurement_method }}{% endif %}
		&nbsp;·&nbsp; {{ doc.name }}
	</p>

	<table class="table table-bordered table-condensed" style="font-size: 9pt;">
		<thead>
			<tr>
				<th style="width: 9%;">{{ _("Ref") }}</th>
				<th>{{ _("Description") }}</th>
				<th style="width: 8%;">{{ _("Unit") }}</th>
				<th style="width: 10%; text-align: right;">{{ _("Qty") }}</th>
				<th style="width: 12%; text-align: right;">{{ _("Rate") }}</th>
				<th style="width: 15%; text-align: right;">{{ _("Amount") }} ({{ doc.currency }})</th>
			</tr>
		</thead>
		<tbody>
		{%- for key in order -%}
			{%- set ns.head = 0 -%}
			<tr><td colspan="6" style="background: #f3f4f2;"><b>{{ frappe.db.get_value("Cost Head", key, "cost_head_name") or key or _("Other work") }}</b></td></tr>
			{%- for row in heads[key] -%}
				{%- if row.is_allowance -%}
					{%- set amount = row.selling_rate -%}
				{%- elif row.draws_from_allowance -%}
					{%- set amount = None -%}
				{%- else -%}
					{%- set amount = frappe.utils.flt((row.selling_rate or 0) * (row.boq_qty or 0), 2) -%}
				{%- endif -%}
				<tr>
					<td>{{ row.boq_ref or row.idx }}</td>
					<td>{{ row.description or row.item_name }}
						{%- if row.is_allowance %} <i>({{ _("provisional sum") }})</i>{% endif -%}
						{%- if row.measurement_notes %}<br><span style="color: #666; font-size: 8pt;">{{ row.measurement_notes }}</span>{% endif -%}
					</td>
					<td>{{ "" if row.is_allowance else (row.uom or "") }}</td>
					<td style="text-align: right;">{{ "" if row.is_allowance else frappe.utils.fmt_money(row.boq_qty, precision=(3 if (row.boq_qty or 0) % 1 else 0)) }}</td>
					<td style="text-align: right;">{{ "" if row.is_allowance else (frappe.utils.fmt_money(row.selling_rate, currency=doc.currency) if row.selling_rate else "—") }}</td>
					<td style="text-align: right;">
						{%- if amount is none -%}<i>{{ _("in provisional sum") }}</i>
						{%- elif amount -%}{{ frappe.utils.fmt_money(amount, currency=doc.currency) }}
						{%- else -%}—{%- endif -%}
					</td>
				</tr>
				{%- set ns.head = ns.head + (amount or 0) -%}
			{%- endfor -%}
			<tr><td colspan="5" style="text-align: right;"><i>{{ _("Total") }}, {{ frappe.db.get_value("Cost Head", key, "cost_head_name") or key or _("Other work") }}</i></td>
				<td style="text-align: right;"><b>{{ frappe.utils.fmt_money(ns.head, currency=doc.currency) }}</b></td></tr>
			{%- set ns.total = ns.total + ns.head -%}
		{%- endfor -%}
		{%- if doc.contingency_amount -%}
			<tr><td>{{ _("CONT") }}</td><td colspan="4">{{ _("Contingency") }}</td>
				<td style="text-align: right;">{{ frappe.utils.fmt_money(doc.contingency_amount, currency=doc.currency) }}</td></tr>
			{%- set ns.total = ns.total + doc.contingency_amount -%}
		{%- endif -%}
		</tbody>
		<tfoot>
			<tr><td colspan="5" style="text-align: right;"><b>{{ _("Tender Total") }}</b></td>
				<td style="text-align: right;"><b>{{ frappe.utils.fmt_money(ns.total, currency=doc.currency) }}</b></td></tr>
		</tfoot>
	</table>
	{%- if doc.unpriced_lines %}
	<p style="color: #8a6412;">{{ _("{0} lines are not priced yet and show as —.").format(doc.unpriced_lines) }}</p>
	{%- endif %}
</div>
